    #[cfg(not(target_arch = "wasm32"))]
    file: File,
    path: PathBuf,
}

impl ReleaseWorkspaceLock {
    /// Acquires the workspace lock outside the checkout.
    ///
    /// `lock_directory` exists for CI and tests. Without it, the lock lives
    /// under the platform's application-data location.
    pub fn acquire(canonical_root: &Path, lock_directory: Option<&Path>) -> Result<Self, VcsError> {
        #[cfg(target_arch = "wasm32")]
        {
            let _ = (canonical_root, lock_directory);
            return Err(VcsError::Git(
                "durable release execution is unavailable on wasm32".to_string(),
            ));
        }
        #[cfg(not(target_arch = "wasm32"))]
        {
            let path = lock_path(canonical_root, lock_directory)?;
            let parent = path.parent().expect("lock path always has a parent");
            fs::create_dir_all(parent)
                .map_err(|_error| VcsError::Git("could not create release lock directory".to_string()))?;
            let file = OpenOptions::new()
                .create(true)
                .read(true)
                .write(true)
                .truncate(false)
                .open(&path)
                .map_err(|_error| VcsError::Git("could not open release workspace lock".to_string()))?;
            file.try_lock_exclusive().map_err(classify_lock_acquire_error)?;
            Ok(Self { file, path })
        }
    }
        VcsError::Git(format!("could not acquire release workspace lock: {error}"))
    }
}

#[cfg(not(target_arch = "wasm32"))]
fn lock_path(canonical_root: &Path, lock_directory: Option<&Path>) -> Result<PathBuf, VcsError> {
    let base = match lock_directory {
        Some(path) => path.to_path_buf(),
        None => platform_lock_directory()?,
    };
    let digest = Sha256::digest(canonical_root.to_string_lossy().as_bytes());
    let key = format!("{:x}", digest);
    Ok(base.join("callisto").join("release-locks").join(format!("{key}.lock")))
}

